<script setup lang="ts">
import {computed,ref} from 'vue';import {Line} from 'vue-chartjs';
import {Chart as ChartJS,CategoryScale,LinearScale,PointElement,LineElement,Tooltip,Legend} from 'chart.js';import {money,dateLabel} from '../lib/format';
import type {Plugin} from 'chart.js';
ChartJS.register(CategoryScale,LinearScale,PointElement,LineElement,Tooltip,Legend);
const props=defineProps<{detail:any;today:string}>();
const table=ref(false);
const todayMarker:Plugin<'line'>={id:'loan-today-marker',afterDraw(chart){const index=chart.data.labels?.findIndex(label=>String(label).startsWith('Today ·'));if(index===undefined||index<0||!chart.chartArea)return;const x=chart.scales.x.getPixelForValue(index),ctx=chart.ctx;ctx.save();ctx.strokeStyle='#71717a';ctx.setLineDash([3,3]);ctx.beginPath();ctx.moveTo(x,chart.chartArea.top);ctx.lineTo(x,chart.chartArea.bottom);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#71717a';ctx.textAlign=x>chart.chartArea.right-35?'right':'left';ctx.fillText('Today',x+3,chart.chartArea.top+10);ctx.restore();}};
const data=computed(()=>{const history=props.detail.balances||[];const projection=[{date:props.today,balance:Number(props.detail.account.balance_cents)}];let balance=Number(props.detail.account.balance_cents);for(const slot of props.detail.scheduled||[]){balance=Math.max(0,balance-Number(slot.amount_cents));projection.push({date:slot.due_date<props.today?props.today:slot.due_date,balance});}const dates=[...new Set<string>([...history.map((e:any)=>e.effective_date),...projection.map(e=>e.date)])].sort();return {labels:dates.map(d=>d===props.today?'Today · '+dateLabel(d):dateLabel(d)),datasets:[{label:'Observed balance',data:dates.map(d=>{const events=history.filter((e:any)=>e.effective_date<=d);return d<=props.today&&events.length?Number(events.at(-1).balance_cents)/100:null;}),borderColor:'#245394',pointRadius:2,stepped:true},{label:'Scheduled balance',data:dates.map(d=>d>=props.today?projection.filter(p=>p.date<=d).at(-1)!.balance/100:null),borderColor:'#245394',borderDash:[6,4],pointRadius:1}]};});
const options:any={responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom'},tooltip:{callbacks:{label:(c:any)=>money(c.raw*100)}}},scales:{x:{grid:{display:false},ticks:{maxTicksLimit:6}},y:{ticks:{callback:(v:any)=>'$'+v}}}};
</script>
<template><div><div class="flex justify-between gap-3"><h3 class="font-medium">Balance over time</h3><button class="help underline" @click="table=!table">{{table?'Chart':'Data table'}}</button></div><p class="help mt-1">Solid: observed balances. Dashed: remaining scheduled payments, with overdue unpaid installments projected from Today. No interest calculation.</p><div v-if="!table" class="mt-4 h-56"><Line :data="data" :options="options" :plugins="[todayMarker]" role="img" aria-label="Loan observed and scheduled balance over time"/></div><div v-else class="mt-4 max-h-80 overflow-auto"><table><thead><tr><th>Date</th><th>Observed</th><th>Scheduled</th></tr></thead><tbody><tr v-for="(label,index) in data.labels" :key="index"><td>{{label}}</td><td>{{data.datasets[0].data[index]===null?'—':money(Number(data.datasets[0].data[index])*100)}}</td><td>{{data.datasets[1].data[index]===null?'—':money(Number(data.datasets[1].data[index])*100)}}</td></tr></tbody></table></div></div></template>
